NavierStokes.NaturalEntrance.EntranceProfile.regular_cone_at_four {h j σ Λ C : ℝ} {P0 : ℝ → ℝ}
  {d : AnalyticInputs h j σ P0} (F : EntranceProfile d Λ C) (hsmall : NaturalAxisRange.Parameters h j) (hΛ : 0 < Λ)
  {η : ℝ} (hη : η ∈ Icc (-1) 1) :
  have p := (4 / Λ, η);
  have q :=
    p.1 * regularAngularLag h F.profile.family.f F.profile.family.U F.profile.family.Ubar p / NaturalAxisData.L h η;
  have n :=
    p.1 * regularAxialLag h F.profile.family.U F.profile.family.Ubar F.profile.family.Pi p /
      (NaturalAxisData.L h η * angularVelocity F.profile.family.f p);
  9 / 4 < q + n ^ 2 / q

